import React from 'react';
import { LockedSolidIcon } from '@fiverr-private/visuals';
import Badge from '../Badge';
import type { BadgePropsWithoutTooltip } from '../../types';

interface KickstartBadgeProps extends BadgePropsWithoutTooltip {
  isLocked?: boolean;
}

const KickstartBadge = ({
  dataTestId,
  isLocked = false,
  dataTrackTag = 'kickstart_badge',
  dataTrackValue,
}: KickstartBadgeProps) => (
  <Badge backgroundColor="pink_900" dataTestId={dataTestId} dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue}>
    {isLocked && <LockedSolidIcon size="xs" />}
    Kickstart
  </Badge>
);

KickstartBadge.displayName = 'KickstartBadge';

export default KickstartBadge;
