import React from 'react';
import { Container, Divider } from '@fiverr-private/layout_components';
import type { Types } from '@fiverr-private/theme';

const DropdownFooter = ({
  withDivider = false,
  children,
  ...rest
}: Types.ContainerProps & { withDivider?: boolean }) => (
  <>
    {withDivider && <Divider marginTop="2" />}
    <Container paddingTop="3" paddingX="2" paddingBottom="1" width="100%" {...rest}>
      {children}
    </Container>
  </>
);

DropdownFooter.displayName = 'DropdownFooter';
DropdownFooter.id = 'DropdownFooter';
export default DropdownFooter;
