import React, { type AriaAttributes } from 'react';
import { translate } from '@fiverr-private/i18n-react';
import { EllipsisIcon } from '@fiverr-private/visuals';
import { IconButton } from '@fiverr-private/button';
import { type Types } from '@fiverr-private/theme';

interface DropdownTriggerProps
  extends Pick<AriaAttributes, 'aria-haspopup' | 'aria-expanded'>,
    Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {
  ariaLabel?: string;
}
const DropdownTrigger = React.forwardRef(
  (
    {
      ariaLabel = translate<string>('dropdown.dropdownTrigger.ariaLabel'),
      'aria-haspopup': ariaHasPopup,
      'aria-expanded': ariaExpanded,
      dataTrackTag = 'dropdown_trigger',
      dataTrackValue,
    }: DropdownTriggerProps,
    ref: React.ForwardedRef<HTMLButtonElement>
  ) => (
    <IconButton
      type="button"
      aria-label={ariaLabel}
      shape="circle"
      ref={ref}
      aria-haspopup={ariaHasPopup}
      aria-expanded={ariaExpanded}
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      <EllipsisIcon color="grey_900" />
    </IconButton>
  )
);

DropdownTrigger.displayName = 'DropdownTrigger';

export default DropdownTrigger;
