import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import { LockedIcon } from '@fiverr-private/visuals';
import Badge from '../Badge';
import type { BadgePropsWithoutTooltip } from '../../types';

const SELLER_PLUS_TAG = 'Plus';

const SellerPlusBadge = ({
  dataTestId,
  dataTrackTag = 'seller_plus_badge',
  dataTrackValue,
  isLocked = false,
}: BadgePropsWithoutTooltip & { isLocked?: boolean }) => (
  <Badge backgroundColor="pink_900" dataTestId={dataTestId} dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue}>
    <Container display="inlineFlex" gap="1">
      {isLocked && <LockedIcon />}
      {SELLER_PLUS_TAG}
    </Container>
  </Badge>
);

SellerPlusBadge.displayName = 'SellerPlusBadge';

export default SellerPlusBadge;
