import React from 'react';
import { I18n } from '@fiverr-private/i18n-react';
import { CalendarIcon } from '@fiverr-private/visuals';
import Highlight from '../Highlight';
import IconWrapper from '../helpers/IconWrapper';

/**
 * @deprecated Please use Highlight from @fiverr-private/data_display package.
 */
const UnavailableHighlight = ({ date }: { date: Date }) => {
  const formattedDate = new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric' }).format(
    date
  );

  return (
    <Highlight type="warning">
      <IconWrapper>
        <CalendarIcon />
      </IconWrapper>
      <I18n
        k="highlights.unavailable"
        params={{
          date: formattedDate,
        }}
      />
    </Highlight>
  );
};

UnavailableHighlight.displayName = 'UnavailableHighlight';

export default UnavailableHighlight;
