import React from 'react';
import { Box } from '@fiverr-private/theme';
import type { HighlightProps } from './types';
import { COLORS_BY_TYPE } from './constants';

const Highlight = ({ type = 'neutral', children, className }: HighlightProps) => (
  <Box
    borderRadius="md"
    display="flex"
    gap="1.5"
    paddingY="1.5"
    paddingX="2.5"
    width="fit-content"
    fontSize="b_sm"
    lineHeight="b_xs"
    fontWeight="semibold"
    userSelect="none"
    className={className}
    {...COLORS_BY_TYPE[type]}
  >
    {children}
  </Box>
);

Highlight.displayName = 'Highlight';

export default Highlight;
