import React from 'react';
import { I18n } from '@fiverr-private/i18n-react';
import Badge from '../Badge';
import type { BadgePropsWithoutTooltip } from '../../types';
import ProTierIcon from './ProTierIcon';
import { ProTierBadgeTier } from './types';

interface ProTierBadgeProps extends BadgePropsWithoutTooltip {
  tier: ProTierBadgeTier;
}

const ProTierBadge = ({
  dataTestId,
  tier,
  dataTrackTag = 'pro_tier_badge',
  dataTrackValue = tier,
}: ProTierBadgeProps) => (
  <Badge
    color="grey_1200"
    backgroundColor="transparent"
    dataTestId={dataTestId}
    dataTrackTag={dataTrackTag}
    dataTrackValue={dataTrackValue}
  >
    <ProTierIcon tier={tier} />
    <I18n k={`badges.pro_tier_badge.${tier}`} />
  </Badge>
);

ProTierBadge.displayName = 'ProTierBadge';

export default ProTierBadge;
